physicalEntities = rel.join@1(left: entities.relation, right: physical.relation, leftKey: "GlobalId", rightKey: "globalId", kind: "semi");
  // Ok  relation 237 rows x 6 cols  sha 8ee2afc729f8  plan 52347b7c0711
  //   columns EntityIndex:Integer, StepId:Integer, GlobalId:Text, Name:Text, Category:Text, Type:Text
