  //   [1] 2073, 8386, "1hOSvn6df7F8_7GcBWlSDm", "M_Single-Flush:0864 x 2032mm:0864 x 2032mm:15047"..., "IFCDOOR", "0864 x 2032mm"
  //   [2] 2561, 12574, "0wkEuT1wr1kOyafLY4vyu$", "M_Tall Cabinet-Single Door(2):800 mm:800 mm:1572"..., "IFCFURNISHINGELEMENT", "800 mm"
physicalNoCsv = rel.join@1(left: physicalEntities.relation, right: csv.relation, leftKey: "GlobalId", rightKey: "GlobalId", kind: "anti");
  // Ok  relation 21 rows x 6 cols  sha e75687c86579  plan 062a7f3282ff
  //   columns EntityIndex:Integer, StepId:Integer, GlobalId:Text, Name:Text, Category:Text, Type:Text
  //   [0] 3013, 1627, "0BTBFw6f90Nfh9rP1dl_CZ", "Living Room", "IFCSPACE", null
  //   [1] 3029, 67, "0BTBFw6f90Nfh9rP1dlXr2", "Living Room", "IFCSPACE", null
  //   [2] 3684, 212, "0BTBFw6f90Nfh9rP1dlXr$", "Kitchen", "IFCSPACE", null
answer = rel.sql@1(t1: csvNoEntity.relation, t2: physicalNoCsv.relation, t3: csvMatchedNonPhysical.relation, sql: "SELECT (SELECT count(*) FROM t1) AS CsvRowsWithNoEntity, (SELECT count(*) FROM t2) AS PhysicalElementsWithNoCsvRow, (SELECT count(*) FROM t3) AS CsvRowsMatchingNonPhysicalEntity");
  // Ok  relation 1 rows x 3 cols  sha fbbe8891c5ce  plan 0779788ee83a
  //   columns CsvRowsWithNoEntity:Integer, PhysicalElementsWithNoCsvRow:Integer, CsvRowsMatchingNonPhysicalEntity:Integer
  //   [0] 0, 21, 52
storeyOf = rel.table@1(source: "duplex-base", table: "StoreyOfElement");
  // Ok  relation 239 rows x 4 cols  sha d6a86ac86ade  plan a8c1aa22dccb
  //   columns EntityIndex:Integer, StoreyIndex:Integer, StoreyName:Text, Depth:Integer
